using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;

namespace AvexPlugin.Features.Export;

public static class ExportEndpoints
{
    public static void Map(IEndpointRouteBuilder endpoints)
    {
        endpoints.MapPost("/api/export/generate", async (ExportRequest req, ExportService svc) =>
        {
            if (string.IsNullOrWhiteSpace(req.Formato))
                return Results.BadRequest(new { error = "formato es requerido" });
            var jobId = await svc.EnqueueAsync(req);
            return Results.Accepted($"/api/export/jobs/{jobId}", new { jobId });
        });
    }
}

