namespace AvexPlugin.Features.Export;

public class ExportService
{
    private readonly IExportQueue _queue;

    public ExportService(IExportQueue queue) => _queue = queue;

    public async Task<string> EnqueueAsync(ExportRequest req)
    {
        var jobId = Guid.NewGuid().ToString("N")[..8];
        await _queue.PublishAsync(new ExportJob(jobId, req.Formato));
        return jobId;
    }
}

public interface IExportQueue
{
    Task PublishAsync(ExportJob job);
}

public record ExportJob(string JobId, string Formato);

using System.Transactions;

namespace AvexPlugin.Features.Export;

public class ExportJobRepository
{
    private readonly IConnectionFactory _connections;

    public ExportJobRepository(IConnectionFactory connections) => _connections = connections;

    public async Task<string> CreateJobAsync(ExportRequest req)
    {
        using var scope = new TransactionScope(TransactionScopeOption.Required,
            new TransactionOptions { IsolationLevel = IsolationLevel.ReadCommitted },
            TransactionScopeAsyncFlowOption.Enabled);
        using var conn = _connections.CreateConnection();
        var jobId = await InsertHeaderAsync(conn, req);
        await InsertDetailRowsAsync(conn, jobId, req.Rows);
        scope.Complete();
        return jobId;
    }
}

